  const [photoNotice, setPhotoNotice] = useState("");
  useEffect(() => { const controller = new AbortController(); setRecognition(null); setPreviewError(""); fetch(`/api/operations/recognition?year=${previewYear}`,{signal:controller.signal}).then(response=>readApiResponse(response)).then(data=>{if(!controller.signal.aborted)setRecognition(data);}).catch(error=>{if(error.name!=="AbortError")setPreviewError(error.message);}); return()=>controller.abort(); }, [previewYear,config.employees]);
  const global = artwork.global || {}; const monthly = artwork.monthly || {}; const hall = artwork.hall || {};
  const setGlobal = (key, value) => setArtwork((current) => ({ ...current, global: { ...(current.global || {}), [key]: value } }));
