  const setHall = (key, value) => setArtwork((current) => ({ ...current, hall: { ...(current.hall || {}), [key]: value } }));
  async function uploadPhoto(employeeId, file) {
    if (!file || uploading) return; setUploading(employeeId); setPhotoNotice(""); const form = new FormData(); form.set("file", file); form.set("employeeId", employeeId); form.set("documentType", "EMPLOYEE_PHOTO"); form.set("displayName", file.name);
    try { const payload = await fetch(`/api/operations/employees/${employeeId}/documents`, { method: "POST", body: form }).then((response) => readApiResponse(response)); if (payload.document?.employeeId !== employeeId) throw new Error("Upload target verification failed"); await reload(); setPhotoNotice(isArabic ? "تم تحديث صورة الموظف" : "Employee photo updated"); }
    catch (error) { setPhotoNotice(error.message); } finally { setUploading(""); }
  }
